def pancake_sort(arr):
    def flip(arr, i):
        """Flip the first i elements of arr."""
        arr[:i] = arr[:i][::-1]

    def sort(arr):
        """Sort arr using pancake sort."""
        n = len(arr)
        for size in range(n, 1, -1):
            # Find the index of the maximum element in the first `size` elements
            max_idx = max(range(size), key=lambda i: arr[i])
            max_val = arr[max_idx]

            # Move the maximum element to the front
            if max_idx != 0:
                flip(arr, max_idx + 1)

            # Move the maximum element to the back of the current sorted section
            if max_idx != size - 1:
                flip(arr, size)

            # Place the maximum element in its final sorted position
            arr[size - 1] = max_val

        return arr

    return sort(arr)
```

