def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)
    target_sum = sum(matrix[0])

    # Check rows
    for i in range(n):
        row_sum = sum(matrix[i])
        if row_sum != target_sum:
            return False

    # Check columns
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != target_sum:
            return False

    # Check diagonals
    diag1 = sum(matrix[i][i] for i in range(n))
    diag2 = sum(matrix[i][n - 1 - i] for i in range(n))
    if diag1 != target_sum or diag2 != target_sum:
        return False

    # Check all numbers are unique and correct (1 to n^2)
    expected_numbers = set(range(1, n * n + 1))
    actual_numbers = set()
    for i in range(n):
        for j in range(n):
            actual_numbers.add(matrix[i][j])

    if expected_numbers != actual_numbers:
        return False

    return True
```

