def max_sum_increasing_subseq(arr, n, i, k):
    # dp[j] will store the maximum sum of an increasing subsequence
    # ending at index j (j >= i)
    dp = [0] * n
    for j in range(i, n):
        dp[j] = arr[j]
        for m in range(i, j):
            if arr[m] < arr[j]:
                dp[j] = max(dp[j], dp[m] + arr[j])

    # Find the maximum sum of an increasing subsequence ending at k
    # that starts from index i or later
    max_sum = dp[k]
    for j in range(i, k):
        if arr[j] < arr[k]:
            max_sum = max(max_sum, dp[j] + arr[k])

    return max_sum

