def rearange_string(s):
    from collections import Counter
    count = Counter(s)
    max_count = max(count.values())
    max_char = [char for char, cnt in count.items() if cnt == max_count]

    if len(s) - max_count >= max_count - 1:
        # Construct the string
        result = []
        remaining = count.copy()
        import heapq
        heap = []
        for char, cnt in remaining.items():
            heapq.heappush(heap, (-cnt, char))

        while heap:
            neg_cnt1, char1 = heapq.heappop(heap)
            result.append(char1)
            remaining[char1] -= 1
            if remaining[char1] > 0:
                heapq.heappush(heap, (-remaining[char1], char1))

            if len(result) - 1 < len(s) - 1:
                if not heap:
                    break
                neg_cnt2, char2 = heapq.heappop(heap)
                result.append(char2)
                remaining[char2] -= 1
                if remaining[char2] > 0:
                    heapq.heappush(heap, (-remaining[char2], char2))

        return ''.join(result)
    else:
        return None
