def ncr_modp(n, r, p):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1 % p
    num = 1
    den = 1
    for i in range(r):
        num = num * (n - i) % p
        den = den * (i + 1) % p
    return num * pow(den, p - 2, p) % p
